-- ==============================================================================
-- BCA ICE CREAM WALA - 1-CLICK AMUL PRODUCTS & OFFICIAL IMAGES UPDATE SCRIPT
-- Run this in your Supabase SQL Editor. Safe to run on live databases without data loss.
-- ==============================================================================

-- 1. Ensure display_order column exists on products
ALTER TABLE public.products ADD COLUMN IF NOT EXISTS display_order INT DEFAULT 0;

-- 2. Ensure Amul Brand exists
VALUES ('a0000000-0000-0000-0000-000000000001', 'amul', 'Amul', 'The Taste of India', '/brands/amul.jpg', '#D62828', 1)
ON CONFLICT (slug) DO UPDATE SET 
    name = EXCLUDED.name, 
    logo = EXCLUDED.logo, 
    color = EXCLUDED.color;

-- 3. Remove old sample Amul rows to prevent primary key or slug collisions
DELETE FROM public.daily_inventory WHERE product_id IN (SELECT id FROM public.products WHERE brand_slug = 'amul' OR slug IN ('amul-rajwadi-kulfi', 'amul-chocolate-brownie', 'amul-vanilla-cup', 'amul-butterscotch-bliss', 'amul-mango-ice-cream'));
DELETE FROM public.order_items WHERE product_id IN (SELECT id FROM public.products WHERE brand_slug = 'amul' OR slug IN ('amul-rajwadi-kulfi', 'amul-chocolate-brownie', 'amul-vanilla-cup', 'amul-butterscotch-bliss', 'amul-mango-ice-cream'));
DELETE FROM public.products WHERE brand_slug = 'amul' OR slug IN ('amul-rajwadi-kulfi', 'amul-chocolate-brownie', 'amul-vanilla-cup', 'amul-butterscotch-bliss', 'amul-mango-ice-cream');

-- 4. Insert All 81 Authentic Amul Products with Official amul.com Images
-- (Notice: We omit the 'id' column so uuid_generate_v4() generates unique non-colliding UUIDs!)
ON CONFLICT (slug) DO UPDATE SET
    name = EXCLUDED.name,
    brand_id = EXCLUDED.brand_id,
    brand_slug = EXCLUDED.brand_slug,
    brand_name = EXCLUDED.brand_name,
    category = EXCLUDED.category,
    description = EXCLUDED.description,
    price = EXCLUDED.price,
    volume = EXCLUDED.volume,
    image = EXCLUDED.image,
    badge = EXCLUDED.badge,
    rating = EXCLUDED.rating,
    rating_count = EXCLUDED.rating_count,
    is_popular = EXCLUDED.is_popular,
    display_order = EXCLUDED.display_order,
    updated_at = NOW();

-- 5. Ensure today's stock session exists
VALUES (
    'c0000000-0000-0000-0000-000000000001',
    to_char(NOW() AT TIME ZONE 'Asia/Kolkata', 'YYYY-MM-DD'),
    'published',
    NOW(),
    'Admin Store Manager',
    2430,
    0,
    'Published stock for all 81 Amul products'
)
ON CONFLICT (session_date) DO UPDATE SET
    status = EXCLUDED.status,
    notes = EXCLUDED.notes;

-- 6. Ensure all Amul products have 30 available stock units today
SELECT 
    'c0000000-0000-0000-0000-000000000001',
    p.id,
    30,
    0,
    0,
    5
FROM public.products p
WHERE p.brand_slug = 'amul'
ON CONFLICT (stock_session_id, product_id) DO UPDATE SET
    published_quantity = EXCLUDED.published_quantity;
